// Own only the DC acquired by GetDC; it must be released with the same HWND.
struct ScopedWindowDC {
    HWND window;
    HDC dc;
    explicit ScopedWindowDC(HWND h) : window(h), dc(GetDC(h)) {}
    ~ScopedWindowDC() {
        if (dc)
            ReleaseDC(window, dc);
    }
    ScopedWindowDC(const ScopedWindowDC&) = delete;
    ScopedWindowDC& operator=(const ScopedWindowDC&) = delete;
};
struct ScopedPaintDC {
    HWND window;
    PAINTSTRUCT paint{};
    HDC dc;
    explicit ScopedPaintDC(HWND h) : window(h), dc(BeginPaint(h, &paint)) {}
    void end() noexcept {
        if (window) {
            EndPaint(window, &paint);
            window = nullptr;
        }
    }
    ~ScopedPaintDC() { end(); }
    ScopedPaintDC(const ScopedPaintDC&) = delete;
    ScopedPaintDC& operator=(const ScopedPaintDC&) = delete;
};
struct ScopedSavedDC {
    HDC dc;
    int state;
    explicit ScopedSavedDC(HDC h) : dc(h), state(h ? SaveDC(h) : 0) {}
    void restore() noexcept {
        if (dc && state) {
            RestoreDC(dc, state);
            state = 0;
        }
    }
    ~ScopedSavedDC() { restore(); }
    ScopedSavedDC(const ScopedSavedDC&) = delete;
    ScopedSavedDC& operator=(const ScopedSavedDC&) = delete;
};
struct ScopedSelection {
    HDC dc = nullptr;
    HGDIOBJ old = nullptr;
    ScopedSelection(HDC d, HGDIOBJ object)
        : dc(d), old(d && object ? SelectObject(d, object) : nullptr) {}
    ~ScopedSelection() {
        if (dc && old && old != HGDI_ERROR)
            SelectObject(dc, old);
    }
    ScopedSelection(const ScopedSelection&) = delete;
    ScopedSelection& operator=(const ScopedSelection&) = delete;
};

