struct BatteryLanguage {
    const LegacyFile* cab;
    const LegacyFile* mui;
    const wchar_t* locale;
    const wchar_t* entry;
};
static const BatteryLanguage& SelectedBatteryLanguage() {
    static const BatteryLanguage it{
        &kBatteryCabIt, &kBatteryMuiIt, L"it-IT",
        L"amd64_microsoft-windows-stobject.resources_31bf3856ad364e35_10.0."
        L"10586.0_it-it_ae7cfb07bf1cbc6f\\stobject.dll.mui"};
    static const BatteryLanguage en{
        &kBatteryCabEn, &kBatteryMuiEn, L"en-US",
        L"amd64_microsoft-windows-stobject.resources_31bf3856ad364e35_10.0."
        L"10586.0_en-us_21d231ddf4f1ceea\\stobject.dll.mui"};
    static const BatteryLanguage es{
        &kBatteryCabEs, &kBatteryMuiEs, L"es-ES",
        L"amd64_microsoft-windows-stobject.resources_31bf3856ad364e35_10.0."
        L"10586.0_es-es_219d8ec1f518c08f\\stobject.dll.mui"};
    static const BatteryLanguage fr{
        &kBatteryCabFr, &kBatteryMuiFr, L"fr-FR",
        L"amd64_microsoft-windows-stobject.resources_31bf3856ad364e35_10.0."
        L"10586.0_fr-fr_c45504c0e7ead6f1\\stobject.dll.mui"};
    static const BatteryLanguage pt{
        &kBatteryCabPt, &kBatteryMuiPt, L"pt-PT",
        L"amd64_microsoft-windows-stobject.resources_31bf3856ad364e35_10.0."
        L"10586.0_pt-pt_245037ce61153c65\\stobject.dll.mui"};
    static const BatteryLanguage br{
        &kBatteryCabBr, &kBatteryMuiBr, L"pt-BR",
        L"amd64_microsoft-windows-stobject.resources_31bf3856ad364e35_10.0."
        L"10586.0_pt-br_236e686261a5cc89\\stobject.dll.mui"};
    switch (CurrentUiLanguage()) {
        case UiLanguage::Italian:
            return it;
        case UiLanguage::Spanish:
            return es;
        case UiLanguage::French:
            return fr;
        case UiLanguage::Portuguese:
            return SUBLANGID(GetUserDefaultUILanguage()) ==
                           SUBLANG_PORTUGUESE_BRAZILIAN
                       ? br
                       : pt;
        default:
            return en;
    }
}
static bool IsBatteryCab(const LegacyFile& spec) {
    return &spec == &kBatteryCabIt || &spec == &kBatteryCabEn ||
           &spec == &kBatteryCabEs || &spec == &kBatteryCabFr ||
           &spec == &kBatteryCabPt || &spec == &kBatteryCabBr;
}
