                // An upward pull opens the Jump List.
                // Decide before horizontal reorder starts; do not install a
                // hook.
                BarEdge edge = s->nativeEdge == ABE_TOP     ? BarEdge::Top
                               : s->nativeEdge == ABE_LEFT  ? BarEdge::Left
                               : s->nativeEdge == ABE_RIGHT ? BarEdge::Right
                                                            : BarEdge::Bottom;
                EdgeDelta gesture = DragRelativeToEdge(edge, dx, dy);
                if (!s->dragActive && gesture.away >= Px(16) &&
                    std::abs(gesture.along) < Px(30)) {
                    size_t index = s->groups.size();
                    for (size_t i = 0; i < s->groups.size(); ++i)
                        if (s->groups[i].key == s->dragKey) {
                            index = i;
                            break;
                        }
                    s->dragCandidate = false;
                    s->dragActive = false;
                    s->dragInsertion = -1;
                    s->dragKey.clear();
                    if (GetCapture() == h)
                        ReleaseCapture();
                    KillTimer(h, TIMER_HOVER);
                    HidePreview();
                    POINT cursor{};
                    GetCursorPos(&cursor);
                    if (index < s->groups.size())
                        ShowJumpList(index, cursor);
                    return 0;
                }
                // Small vertical movements remain candidates for the upward
                // pull.
                if (!s->dragActive && gesture.away > 0 &&
                    gesture.away > std::abs(gesture.along))
                    return 0;
