            s->win10Pressed = HIT_NONE;
            s->desktopArrowHot = false;
            s->linksArrowHot = false;
            s->fadeTick = GetTickCount64();
            SetTimer(h, TIMER_FADE, 16, nullptr);
            KillTimer(h, TIMER_HOVER);
            KillTimer(h, TIMER_DESKTOP_PEEK);
